package com.tradingplatform.prediction;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.tradingplatform.market.*; import com.tradingplatform.persistence.*;
import java.math.BigDecimal; import java.net.URI; import java.net.http.*; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Service;
@Service public class NiftyPredictionService {
 private final MarketDataService market; private final ObjectMapper json; private final PredictionRepository repository; private final StringRedisTemplate redis; private final String mlUrl; private final HttpClient http=HttpClient.newHttpClient();
 public NiftyPredictionService(MarketDataService market,ObjectMapper json,PredictionRepository repository,StringRedisTemplate redis,@Value("${trading.ml-service-url:http://localhost:8000}")String mlUrl){this.market=market;this.json=json;this.repository=repository;this.redis=redis;this.mlUrl=mlUrl;}
 public Map<String,Object> predict(int horizon, double threshold) {
  String cacheKey="prediction:nifty:"+horizon+":"+threshold; String cached=redis.opsForValue().get(cacheKey); if(cached!=null)try{return json.readValue(cached,new TypeReference<>(){});}catch(Exception ignored){}
  List<Candle> candles=market.intraday("NIFTY",Timeframe.parse("1m")); if(candles.size()<30)throw new MarketDataUnavailableException("At least 30 one-minute NIFTY candles are required for a prediction.");
  Map<String,Object> body=new LinkedHashMap<>(); body.put("symbol","NIFTY");body.put("horizon_minutes",horizon);body.put("movement_threshold_percent",threshold);body.put("candles",candles);body.put("option_features",Map.of());
  try { HttpRequest request=HttpRequest.newBuilder(URI.create(mlUrl+"/api/v1/nifty/predict")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).timeout(Duration.ofSeconds(15)).build(); HttpResponse<String> response=http.send(request,HttpResponse.BodyHandlers.ofString()); if(response.statusCode()==503)throw new MarketDataUnavailableException("NIFTY ML model is untrained; prediction is intentionally unavailable."); if(response.statusCode()/100!=2)throw new MarketDataUnavailableException("Prediction service rejected the market data."); Map<String,Object> result=json.readValue(response.body(),new TypeReference<>(){}); persist(result); redis.opsForValue().set(cacheKey,response.body(),Duration.ofSeconds(30)); return result; }catch(MarketDataUnavailableException e){throw e;}catch(Exception e){throw new MarketDataUnavailableException("Prediction service is unavailable.",e);}
 }
 public List<PredictionEntity> history(){return repository.findTop100BySymbolOrderByTimestampDesc("NIFTY");}
 public Map<String,Object> modelStatus(){try{HttpRequest r=HttpRequest.newBuilder(URI.create(mlUrl+"/api/v1/model/status")).GET().timeout(Duration.ofSeconds(5)).build();return json.readValue(http.send(r,HttpResponse.BodyHandlers.ofString()).body(),new TypeReference<>(){});}catch(Exception e){return Map.of("status","UNAVAILABLE");}}
 @SuppressWarnings("unchecked") private void persist(Map<String,Object> r){ PredictionEntity e=new PredictionEntity();e.id=UUID.randomUUID();e.symbol="NIFTY";e.timestamp=instant(r.get("timestamp"),Instant.now());e.contextTimestamp=instant(r.get("contextTimestamp"),e.timestamp);e.horizonMinutes=((Number)r.getOrDefault("horizonMinutes",15)).intValue();e.decision=String.valueOf(r.getOrDefault("decision","NO_TRADE"));e.reason=String.valueOf(r.getOrDefault("reason",""));e.modelVersion=String.valueOf(r.getOrDefault("modelVersion","untrained"));e.featureVersion=String.valueOf(r.getOrDefault("featureVersion",null));e.featureSchemaVersion=String.valueOf(r.getOrDefault("featureSchemaVersion",e.featureVersion));e.inputHash=(String)r.get("inputHash");e.prediction=(String)r.get("prediction");e.confidence=String.valueOf(r.getOrDefault("confidence",null));e.niftyPrice=decimal(r.get("niftyPrice"));e.expectedMovePoints=decimal(r.get("expectedMovePoints"));e.predictedReturnPercent=decimal(r.get("predictedReturnPercent"));e.predictedRangeLow=decimal(r.get("predictedRangeLow"));e.predictedRangeHigh=decimal(r.get("predictedRangeHigh"));Map<String,Object> p=(Map<String,Object>)r.getOrDefault("probabilities",Map.of());e.upProbability=decimal(p.getOrDefault("up",p.get("UP")));e.downProbability=decimal(p.getOrDefault("down",p.get("DOWN")));e.sidewaysProbability=decimal(p.getOrDefault("sideways",p.getOrDefault("NEUTRAL",p.get("FLAT"))));e.createdAt=Instant.now();repository.save(e); }
 private static Instant instant(Object value,Instant fallback){if(value==null)return fallback;try{return Instant.parse(value.toString());}catch(Exception ignored){return fallback;}}
 private static BigDecimal decimal(Object value){return value==null?null:new BigDecimal(value.toString());}
}
